//! Replays the golden corpus generated by
//! `electricity/scripts/generate_scripted_corpus.py` -- real output
//! from Circuitry's own `circuitry.adapters.scripted.ScriptedAdapter`
//! (`check()`/`generate()`, driven through real replies files, never a
//! private helper reached into directly) against this crate's own
//! `ScriptedAdapter`.
//!
//! The corpus is checked in (`tests/golden/scripted_corpus.json`); CI
//! separately regenerates it with Python 3.11 and fails the build if it
//! differs (`.github/workflows/electricity-generated.yml`), so this
//! test only needs to trust the committed file.
//!
//! Every case's own replies file is written under a fresh temp
//! directory and the adapter is built with a bare, relative filename
//! (matching the generator's own `cwd`-relative convention) -- this
//! test `chdir`s into that directory for the span of one case, run
//! sequentially (never two cases' filesystem state interleaved), since
//! `std::env::set_current_dir` is process-global.

use electricity_bytecode::EffectPath;
use electricity_value::{CancellationToken, Value};
use electricity_vm::adapter::{CallContext, ChatMessage, GenerateOptions, ImageInput};
use serde::Deserialize;
use std::path::PathBuf;
use std::sync::atomic::{AtomicU64, Ordering};

static COUNTER: AtomicU64 = AtomicU64::new(0);

struct TempDir(PathBuf);

impl TempDir {
    fn new() -> Self {
        let n = COUNTER.fetch_add(1, Ordering::Relaxed);
        let dir = std::env::temp_dir().join(format!(
            "electricity-scripted-corpus-{}-{n}",
            std::process::id()
        ));
        std::fs::create_dir_all(&dir).unwrap();
        TempDir(dir)
    }
}

impl Drop for TempDir {
    fn drop(&mut self) {
        let _ = std::fs::remove_dir_all(&self.0);
    }
}

#[derive(Deserialize)]
struct RetryCase {
    retryable: bool,
    /// `f64`, not `u16`/`u32`: a few corpus cases carry a status far
    /// beyond any integer width (the "status beyond `u16`" divergence
    /// case) -- `serde_json`'s default `Number` already coerces an
    /// out-of-i64/u64-range literal to a lossy `f64` without the
    /// `arbitrary_precision` feature, so this is simply naming that
    /// coercion explicitly rather than fighting it. The comparison
    /// below only needs "fits `u16`" vs. "doesn't", never the exact
    /// magnitude of an out-of-range value.
    status: Option<f64>,
    retry_after: Option<String>,
    error_code: Option<String>,
}

#[derive(Deserialize)]
struct GenerateOk {
    text: String,
    tokens_sent: Option<i64>,
    tokens_received: Option<i64>,
    finish_reason: Option<String>,
    warnings: Vec<String>,
}

#[derive(Deserialize)]
struct CallCase {
    kind: String,
    path: Option<String>,
    // `check` results.
    ok: Option<CheckOkOrBool>,
    message: Option<String>,
    // `generate` results.
    error_class: Option<String>,
    retry: Option<RetryCase>,
}

/// `ok` means two different things in the corpus depending on `kind`:
/// a `check` call's own plain boolean, or a `generate` call's own
/// success payload (absent entirely on a `generate` failure) -- this
/// untagged enum lets one `CallCase` struct read both without a
/// separate type per `kind`.
#[derive(Deserialize)]
#[serde(untagged)]
enum CheckOkOrBool {
    Bool(bool),
    Generate(GenerateOk),
}

#[derive(Deserialize)]
struct RepliesCase {
    case: String,
    filename: String,
    contents: String,
    raw_bytes_hex: Option<String>,
    calls: Vec<CallCase>,
}

#[derive(Deserialize)]
struct OptionsInput {
    temperature: Option<f64>,
    max_tokens: Option<i64>,
    stop: Vec<String>,
    params: serde_json::Map<String, serde_json::Value>,
    messages_count: usize,
    images_count: usize,
    used: Vec<String>,
}

#[derive(Deserialize)]
struct OptionsCase {
    case: String,
    input: OptionsInput,
    set_fields: Vec<String>,
    warnings: Vec<String>,
}

#[derive(Deserialize)]
struct MergeCase {
    case: String,
    per_instance_counts: Vec<std::collections::HashMap<String, usize>>,
    merged: std::collections::HashMap<String, usize>,
}

#[derive(Deserialize)]
struct Corpus {
    replies_cases: Vec<RepliesCase>,
    options_cases: Vec<OptionsCase>,
    merge_cases: Vec<MergeCase>,
    host_claude_message: String,
}

fn corpus() -> Corpus {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/golden/scripted_corpus.json");
    let text = std::fs::read_to_string(&path).expect("read scripted_corpus.json");
    serde_json::from_str(&text).expect("parse scripted_corpus.json")
}

/// `"prime.x"`/`"prime.unknown"` -> an [`EffectPath`] -- every corpus
/// path starts with the implicit `prime` root [`EffectPath::root`]
/// already supplies.
fn path_from_dotted(dotted: &str) -> EffectPath {
    let mut segments = dotted.split('.');
    assert_eq!(
        segments.next(),
        Some("prime"),
        "every corpus path starts with prime"
    );
    let mut path = EffectPath::root();
    for segment in segments {
        path = path.push_name(segment);
    }
    path
}

async fn run_replies_case(case: RepliesCase, failures: &mut Vec<String>) {
    let dir = TempDir::new();
    let file_path = dir.0.join(&case.filename);
    match &case.raw_bytes_hex {
        // Only the invalid-UTF-8 case sets this: JSON text can't carry
        // the raw bytes directly, so the generator hex-encodes them
        // instead of writing `contents` (itself just a human-readable
        // placeholder for this one case).
        Some(hex) => {
            let bytes: Vec<u8> = (0..hex.len())
                .step_by(2)
                .map(|i| u8::from_str_radix(&hex[i..i + 2], 16).unwrap())
                .collect();
            std::fs::write(&file_path, &bytes).unwrap();
        }
        None => std::fs::write(&file_path, &case.contents).unwrap(),
    }
    let mut cfg = electricity_value::Dict::new();
    cfg.insert(
        Value::Str("replies_file".to_string()),
        Value::Str(case.filename.clone()),
    );
    let adapter = electricity_adapters::scripted::build_scripted("scripted", &Value::Dict(cfg))
        .expect("build_scripted never fails");
    let previous_cwd = std::env::current_dir().unwrap();
    std::env::set_current_dir(&dir.0).unwrap();
    let token = CancellationToken::new();
    for call in case.calls {
        match call.kind.as_str() {
            "check" => {
                let result = adapter.check().await;
                let expected_ok = matches!(call.ok, Some(CheckOkOrBool::Bool(true)));
                // Issue #478: a YAML parse-error text is only ever
                // compared "by location", never byte-for-byte --
                // `electricity-yaml`'s own error text doesn't reproduce
                // PyYAML's multi-line `in "<unicode string>", line N,
                // column N: ...` mark format. Every other message here
                // (JSON, `OSError`, the structural-validation texts,
                // the `check() raised ...` fold) is still compared
                // exactly.
                let message_matches = match (&result.message, &call.message) {
                    (Some(got), Some(want)) if want.contains("invalid YAML: ") => {
                        let prefix = format!("{}: invalid YAML: ", case.filename);
                        got.starts_with(&prefix) && want.starts_with(&prefix)
                    }
                    (got, want) => got == want,
                };
                if result.ok != expected_ok || !message_matches {
                    failures.push(format!(
                        "{}: check() = ok:{} message:{:?}, want ok:{expected_ok} message:{:?}",
                        case.case, result.ok, result.message, call.message
                    ));
                }
            }
            "generate" => {
                let dotted = call.path.clone().expect("generate call needs a path");
                let effect_path = path_from_dotted(&dotted);
                let ctx = CallContext {
                    path: &effect_path,
                    timeout_seconds: 30,
                    token: &token,
                };
                let result = adapter
                    .generate("m", "p", &GenerateOptions::default(), &ctx)
                    .await;
                match (result, call.ok, call.error_class.as_deref()) {
                    (Ok(got), Some(CheckOkOrBool::Generate(want)), None) => {
                        if got.text != want.text
                            || got.tokens_sent != want.tokens_sent
                            || got.tokens_received != want.tokens_received
                            || got.finish_reason != want.finish_reason
                            || got.warnings != want.warnings
                        {
                            failures.push(format!(
                                "{}: generate({dotted}) ok mismatch: got {got:?}",
                                case.case
                            ));
                        }
                    }
                    (Err(err), None, Some(class)) => {
                        if err.py_class.name() != class || err.message != call.message.unwrap() {
                            failures.push(format!(
                                "{}: generate({dotted}) err mismatch: got class {} message {:?}",
                                case.case,
                                err.py_class.name(),
                                err.message
                            ));
                        }
                        if let Some(want_retry) = call.retry {
                            let status_matches = match (want_retry.status, err.retry.status) {
                                (None, None) => true,
                                (Some(n), Some(actual)) if n.abs() < 65536.0 => {
                                    n as i64 == i64::from(actual)
                                }
                                // A status too large for `u16` (the one
                                // divergence case) stores as `None` on
                                // the Rust side; Python's own full-
                                // precision value is still huge here.
                                (Some(n), None) if n.abs() >= 65536.0 => true,
                                _ => false,
                            };
                            if err.retry.retryable != want_retry.retryable
                                || !status_matches
                                || err.retry.retry_after != want_retry.retry_after
                                || err.retry.error_code != want_retry.error_code
                            {
                                failures.push(format!(
                                    "{}: generate({dotted}) retry mismatch: got {:?}",
                                    case.case, err.retry
                                ));
                            }
                        }
                    }
                    (got, _, _) => {
                        failures.push(format!(
                            "{}: generate({dotted}) shape mismatch: got {}",
                            case.case,
                            if got.is_ok() { "Ok" } else { "Err" }
                        ));
                    }
                }
            }
            other => panic!("unknown call kind {other}"),
        }
    }
    std::env::set_current_dir(previous_cwd).unwrap();
}

fn check_options_case(case: OptionsCase, failures: &mut Vec<String>) {
    let mut params = electricity_value::Dict::new();
    for (k, v) in case.input.params {
        let value = match v {
            serde_json::Value::Number(n) => Value::Int(electricity_value::IntValue::Small(
                n.as_i64().expect("test params are small ints"),
            )),
            other => panic!("unsupported params value in corpus: {other:?}"),
        };
        params.insert(Value::Str(k), value);
    }
    let messages: Vec<ChatMessage> = (0..case.input.messages_count)
        .map(|_| ChatMessage {
            role: "user".to_string(),
            content: String::new(),
        })
        .collect();
    let images: Vec<ImageInput> = (0..case.input.images_count)
        .map(|_| ImageInput {
            data: None,
            media_type: None,
            url: None,
        })
        .collect();
    let options = GenerateOptions {
        temperature: case.input.temperature,
        max_tokens: case.input.max_tokens,
        stop: case.input.stop,
        params: if params.is_empty() {
            Value::None
        } else {
            Value::Dict(params)
        },
        messages,
        images,
        ..GenerateOptions::default()
    };
    let got_set_fields = electricity_adapters::set_fields(&options);
    if got_set_fields != case.set_fields {
        failures.push(format!(
            "{}: set_fields mismatch: got {got_set_fields:?}, want {:?}",
            case.case, case.set_fields
        ));
    }
    let used: Vec<&str> = case.input.used.iter().map(String::as_str).collect();
    let got_warnings = electricity_adapters::ignored_options_warning("scripted", &options, &used);
    if got_warnings != case.warnings {
        failures.push(format!(
            "{}: ignored_options_warning mismatch: got {got_warnings:?}, want {:?}",
            case.case, case.warnings
        ));
    }
}

#[tokio::test]
async fn scripted_corpus_matches_circuitrys_own_adapter() {
    let data = corpus();
    let mut failures = Vec::new();

    for case in data.replies_cases {
        run_replies_case(case, &mut failures).await;
    }
    for case in data.options_cases {
        check_options_case(case, &mut failures);
    }
    for case in data.merge_cases {
        let got = electricity_adapters::merge_remaining_counts(&case.per_instance_counts);
        if got != case.merged {
            failures.push(format!(
                "{}: merge_remaining_counts mismatch: got {got:?}, want {:?}",
                case.case, case.merged
            ));
        }
    }

    let host_claude_err =
        match electricity_adapters::host_claude::build_host_claude("host_claude", &Value::None) {
            Err(err) => err,
            Ok(_) => panic!("build_host_claude always fails"),
        };
    if host_claude_err.message != data.host_claude_message {
        failures.push(format!(
            "host_claude message mismatch: got {:?}, want {:?}",
            host_claude_err.message, data.host_claude_message
        ));
    }

    assert!(failures.is_empty(), "{}", failures.join("\n"));
}
